package com.group01.assessment.infrastructure.persistence.adapter; import com.group01.assessment.domain.entity.VideoPracticeAttempt; import com.group01.assessment.domain.repository.VideoPracticeAttemptRepository; import com.group01.assessment.infrastructure.persistence.mapper.AssessmentPersistenceMapper; import com.group01.assessment.infrastructure.persistence.repository.VideoPracticeAttemptJpaRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class VideoPracticeAttemptRepositoryAdapter implements VideoPracticeAttemptRepository{private final VideoPracticeAttemptJpaRepository repository;private final AssessmentPersistenceMapper mapper;public VideoPracticeAttemptRepositoryAdapter(VideoPracticeAttemptJpaRepository repository,AssessmentPersistenceMapper mapper){this.repository=repository;this.mapper=mapper;}public VideoPracticeAttempt save(VideoPracticeAttempt v){return mapper.toDomain(repository.save(mapper.toEntity(v)));}public Optional<VideoPracticeAttempt> findByIdAndUserId(UUID id,UUID userId){return repository.findByIdAndUserId(id,userId).map(mapper::toDomain);}}
